use crate::{domain::{activity::{ActivityCategory,ActivityEvent},detached_operation::{classify_systemd_show,DetachedUnitState},device::{Device,validate_ssh_username},managed_workload::ManagedWorkload,managed_workload_operation::{ManagedWorkloadOperation,ManagedWorkloadOperationState,ManagedWorkloadDispatchState,ManagedWorkloadFailure},managed_workload_prepare::{parse_prepare,fingerprint,PrepareContractError,TargetRevision},managed_workload_verify::{parse_verify,VerifyContractError}},infrastructure::{managed_workload_trust::{trust_probe_command,parse_trust_probe,ACTION_ROOT},ssh::{RemoteExecutor,RemoteOutputLimits,SshTarget}},monitoring::maintenance_coordinator::{DeviceMaintenanceCoordinator,MaintenanceOperationKind},storage::{activity_repository::{ActivityRepository,JsonActivityRepository},device_repository::{DeviceRepository,JsonDeviceRepository},managed_workload_repository::{ManagedWorkloadRepository,JsonManagedWorkloadRepository},managed_workload_operation_repository::JsonManagedWorkloadOperationRepository}};
const LIMITS:RemoteOutputLimits=RemoteOutputLimits{stdout:32*1024,stderr:16*1024}; const TIMEOUT:Duration=Duration::from_secs(15);
#[derive(Debug,Clone)] pub struct PreparedWorkload { pub operation:ManagedWorkloadOperation,pub change_count:u32 }
#[derive(Debug,Clone,Copy,PartialEq,Eq)] pub enum PrepareError { WorkloadNotFound,WorkloadDisabled,DeviceTargetUnavailable,MaintenanceConflict,ActionTrustFailed,ActionUnavailable,TransportFailed,TimedOut,OutputLimitExceeded,PrepareProtocolInvalid,PrepareProtocolUnsupported,TargetRevisionInvalid,PersistenceFailed,Internal }
impl fmt::Display for PrepareError { fn fmt(&self,f:&mut fmt::Formatter<'_>)->fmt::Result { write!(f,"{}",match self { Self::WorkloadNotFound=>"Managed workload is unavailable.",Self::WorkloadDisabled=>"Managed workload is disabled.",Self::DeviceTargetUnavailable=>"Configured device is unavailable.",Self::MaintenanceConflict=>"Another maintenance action is active.",Self::ActionTrustFailed=>"Managed action trust validation failed.",Self::ActionUnavailable=>"Managed action is unavailable.",Self::TransportFailed=>"Device communication failed.",Self::TimedOut=>"Preparation timed out.",Self::OutputLimitExceeded=>"Preparation output exceeded its safety limit.",Self::PrepareProtocolInvalid=>"Managed action returned an invalid prepare result.",Self::PrepareProtocolUnsupported=>"Managed action protocol is unsupported.",Self::TargetRevisionInvalid=>"Managed action returned an invalid target revision.",Self::PersistenceFailed=>"Could not save preparation state.",Self::Internal=>"Preparation could not be completed."})}}
fn ssh_error(e:&crate::infrastructure::ssh::SshError)->PrepareError{match e{crate::infrastructure::ssh::SshError::RemoteCommandTimeout|crate::infrastructure::ssh::SshError::ConnectionTimeout=>PrepareError::TimedOut,crate::infrastructure::ssh::SshError::OutputLimitExceeded=>PrepareError::OutputLimitExceeded,_=>PrepareError::TransportFailed}}
fn trust_error(e:&crate::infrastructure::managed_workload_trust::ActionTrustError)->PrepareError{match e{crate::infrastructure::managed_workload_trust::ActionTrustError::ActionUnavailable|crate::infrastructure::managed_workload_trust::ActionTrustError::CapabilityFailure|crate::infrastructure::managed_workload_trust::ActionTrustError::UnsupportedPlatform=>PrepareError::ActionUnavailable,_=>PrepareError::ActionTrustFailed}}
fn protocol_error(e:PrepareContractError)->PrepareError{match e{PrepareContractError::UnsupportedVersion=>PrepareError::PrepareProtocolUnsupported,PrepareContractError::InvalidTarget=>PrepareError::TargetRevisionInvalid,PrepareContractError::Malformed=>PrepareError::PrepareProtocolInvalid}}
#[derive(Debug,Clone,Copy,PartialEq,Eq)] pub enum VerificationError { InvalidLifecycle,WorkloadUnavailable,DeviceTargetUnavailable,TrustFailed,TransportFailed,TimedOut,OutputLimitExceeded,ProtocolInvalid,ProtocolUnsupported,DeployedRevisionMismatch,PersistenceFailed,Internal }
impl fmt::Display for VerificationError {fn fmt(&self,f:&mut fmt::Formatter<'_>)->fmt::Result{write!(f,"{}",match self{Self::InvalidLifecycle=>"Managed workload is not awaiting verification.",Self::WorkloadUnavailable=>"Managed workload configuration is unavailable.",Self::DeviceTargetUnavailable=>"Configured device is unavailable.",Self::TrustFailed=>"Managed action trust validation failed.",Self::TransportFailed=>"Device communication failed.",Self::TimedOut=>"Verification timed out.",Self::OutputLimitExceeded=>"Verification output exceeded its safety limit.",Self::ProtocolInvalid=>"Managed action returned an invalid verification result.",Self::ProtocolUnsupported=>"Managed action verification protocol is unsupported.",Self::DeployedRevisionMismatch=>"Managed workload revision verification failed.",Self::PersistenceFailed=>"Could not save verification state.",Self::Internal=>"Managed workload verification could not be completed."})}}
fn verification_ssh_error(e:&crate::infrastructure::ssh::SshError)->VerificationError{match e{crate::infrastructure::ssh::SshError::RemoteCommandTimeout|crate::infrastructure::ssh::SshError::ConnectionTimeout=>VerificationError::TimedOut,crate::infrastructure::ssh::SshError::OutputLimitExceeded=>VerificationError::OutputLimitExceeded,_=>VerificationError::TransportFailed}}
fn verification_protocol_error(e:VerifyContractError)->VerificationError{match e{VerifyContractError::Malformed=>VerificationError::ProtocolInvalid,VerifyContractError::UnsupportedVersion=>VerificationError::ProtocolUnsupported}}
fn verification(w:&ManagedWorkload)->Vec<String>{let mut v=Vec::new();if let Some(p)=&w.compose_project{v.push(format!("compose:{p}"))}v.extend(w.required_compose_services.iter().map(|s|format!("service:{s}")));v.extend(w.required_service_health_ids.iter().map(|s|format!("health:{s}")));v}
fn target(device:&Device)->SshTarget{SshTarget{host:device.host.clone(),port:device.ssh_port,username:device.ssh_username.clone()}}
struct PrepareEvidence{action_digest:String,target_revision:TargetRevision,fingerprint:String,change_count:u32}
fn prepare_evidence(w:&ManagedWorkload,device:&Device,executor:&dyn RemoteExecutor)->Result<PrepareEvidence,PrepareError>{let target=target(device);let trust=executor.execute_bounded(&target,&trust_probe_command(&w.action_id).map_err(|e|trust_error(&e))?,TIMEOUT,LIMITS).map_err(|e|ssh_error(&e))?;let action=parse_trust_probe(&w.action_id,&trust.stdout).map_err(|e|trust_error(&e))?;let command=format!("'{ACTION_ROOT}/{}' prepare",w.action_id);let reply=executor.execute_bounded(&target,&command,TIMEOUT,LIMITS).map_err(|e|ssh_error(&e))?;let plan=parse_prepare(&reply.stdout).map_err(protocol_error)?;let fp=fingerprint(&w.id,w.config_revision,&action.sha256,&plan.target_revision,&verification(w));Ok(PrepareEvidence{action_digest:action.sha256,target_revision:plan.target_revision,fingerprint:fp.0,change_count:plan.change_count})}
#[derive(Debug,Clone,PartialEq,Eq)] pub(crate) struct DispatchEligible{operation:ManagedWorkloadOperation,action_id:String,target_revision:TargetRevision,principal:String,target:SshTarget}
#[derive(Debug,Clone,PartialEq,Eq)] pub(crate) enum DispatchConsent{DispatchEligible(DispatchEligible),PlanChanged}
#[derive(Debug,Clone)] pub(crate) struct DispatchPrepared{operation:ManagedWorkloadOperation,command:String,target:SshTarget}
