pub(crate) fn revalidate_dispatch_consent_with(dir:&std::path::Path,prepared:&ManagedWorkloadOperation,executor:&dyn RemoteExecutor,coordinator:&DeviceMaintenanceCoordinator)->Result<DispatchConsent,PrepareError>{if prepared.state!=ManagedWorkloadOperationState::Prepared{return Err(PrepareError::Internal)}let _claim=coordinator.try_claim(&prepared.device_id,MaintenanceOperationKind::WorkloadDeploy).ok_or(PrepareError::MaintenanceConflict)?;let workloads=JsonManagedWorkloadRepository::new(dir).load();let w=workloads.workloads.into_iter().find(|w|w.id==prepared.workload_id).ok_or(PrepareError::WorkloadNotFound)?;if !w.enabled{return Err(PrepareError::WorkloadDisabled)}let device=JsonDeviceRepository::new(dir).load_all().into_iter().find(|d|d.id==w.device_id).ok_or(PrepareError::DeviceTargetUnavailable)?;validate_ssh_username(&device.ssh_username).map_err(|_|PrepareError::DeviceTargetUnavailable)?;let fresh=prepare_evidence(&w,&device,executor)?;Ok(if fresh.fingerprint==prepared.deployment_fingerprint{DispatchConsent::DispatchEligible(DispatchEligible{operation:prepared.clone(),action_id:w.action_id,target_revision:fresh.target_revision,principal:device.ssh_username.clone(),target:target(&device)})}else{DispatchConsent::PlanChanged})}
fn fixed_detached_dispatch_command(unit:&str,action_id:&str,target:&TargetRevision,principal:&str)->Option<String>{(ManagedWorkloadOperation::is_valid_transient_unit_id(unit)&&trust_probe_command(action_id).is_ok()&&validate_ssh_username(principal).is_ok()).then(||format!("sudo -n systemd-run --unit={unit} --service-type=exec --property=RemainAfterExit=yes --property=User={principal} -- {ACTION_ROOT}/{action_id} apply {}",target.as_str()))}
pub(crate) fn prepare_detached_dispatch(dir:&std::path::Path,eligible:DispatchEligible)->Result<DispatchPrepared,PrepareError>{let unit=format!("pihub-workload-{}.service",uuid::Uuid::new_v4().simple());debug_assert!(ManagedWorkloadOperation::is_valid_transient_unit_id(&unit));let command=fixed_detached_dispatch_command(&unit,&eligible.action_id,&eligible.target_revision,&eligible.principal).ok_or(PrepareError::Internal)?;let mut operation=eligible.operation;operation.transient_unit_id=Some(unit);operation.state=ManagedWorkloadOperationState::DispatchPrepared;operation.dispatch_state=ManagedWorkloadDispatchState::NotAttempted;operation.observation_deadline=Some((Utc::now()+ChronoDuration::minutes(60)).to_rfc3339());JsonManagedWorkloadOperationRepository::new(dir).save(&operation).map_err(|_|PrepareError::PersistenceFailed)?;Ok(DispatchPrepared{operation,command,target:eligible.target})}
fn emit_workload_activity(repo:&JsonManagedWorkloadOperationRepository,activity:&JsonActivityRepository,operation:&mut ManagedWorkloadOperation,initiated:bool){if initiated{if operation.initiated_activity_emitted{return}operation.initiated_activity_emitted=true}else{if operation.failure_activity_emitted{return}operation.failure_activity_emitted=true}if repo.save(operation).is_err(){if initiated{operation.initiated_activity_emitted=false}else{operation.failure_activity_emitted=false}return}let(code,summary)=if initiated{("workload_deploy.initiated","Managed workload deployment initiated.")}else{("workload_deploy.failed","Managed workload deployment failed.")};let _=activity.append(ActivityEvent::new(ActivityCategory::Administration,code,Some(operation.device_id.clone()),None,None,summary));}
pub(crate) fn dispatch_prepared_with(dir:&std::path::Path,prepared:DispatchPrepared,executor:&dyn RemoteExecutor)->Result<ManagedWorkloadOperation,PrepareError>{let repo=JsonManagedWorkloadOperationRepository::new(dir);if repo.get(&prepared.operation.device_id,&prepared.operation.workload_id).as_ref()!=Some(&prepared.operation){return Err(PrepareError::PersistenceFailed)}let mut operation=prepared.operation;operation.state=ManagedWorkloadOperationState::Dispatching;operation.dispatch_state=ManagedWorkloadDispatchState::Attempted;repo.save(&operation).map_err(|_|PrepareError::PersistenceFailed)?;match executor.execute_bounded(&prepared.target,&prepared.command,TIMEOUT,LIMITS){Ok(result)if result.exit_code==Some(0)&&!result.timed_out=>{operation.state=ManagedWorkloadOperationState::Deploying;operation.dispatch_state=ManagedWorkloadDispatchState::Accepted;operation.failure=None;} _=>{operation.state=ManagedWorkloadOperationState::DispatchUncertain;operation.dispatch_state=ManagedWorkloadDispatchState::Uncertain;operation.failure=Some(crate::domain::managed_workload_operation::ManagedWorkloadFailure::OutcomeUncertain);}}repo.save(&operation).map_err(|_|PrepareError::PersistenceFailed)?;if operation.state==ManagedWorkloadOperationState::Deploying{emit_workload_activity(&repo,&JsonActivityRepository::new(dir),&mut operation,true)}Ok(operation)}
fn fixed_detached_status_command(unit:&str)->Option<String>{ManagedWorkloadOperation::is_valid_transient_unit_id(unit).then(||format!("sudo -n systemctl show --property=LoadState --property=ActiveState --property=SubState --property=Result --property=ExecMainCode --property=ExecMainStatus --property=ExecMainStartTimestampMonotonic --property=ExecMainExitTimestampMonotonic -- {unit}"))}
fn observation_expired(operation:&ManagedWorkloadOperation)->bool{operation.observation_deadline.as_deref().and_then(|v|DateTime::parse_from_rfc3339(v).ok()).is_some_and(|v|v<=Utc::now())}
pub(crate) fn reconcile_detached_workload_with(dir:&std::path::Path,persisted:&ManagedWorkloadOperation,executor:&dyn RemoteExecutor)->Result<ManagedWorkloadOperation,PrepareError>{let repo=JsonManagedWorkloadOperationRepository::new(dir);if repo.get(&persisted.device_id,&persisted.workload_id).as_ref()!=Some(persisted){return Err(PrepareError::PersistenceFailed)}if !persisted.requires_recovery()&&persisted.state!=ManagedWorkloadOperationState::StillRunning{return Err(PrepareError::Internal)}let mut operation=persisted.clone();if operation.state!=ManagedWorkloadOperationState::StillRunning&&observation_expired(&operation){operation.state=ManagedWorkloadOperationState::StillRunning;operation.failure=Some(ManagedWorkloadFailure::StillRunning);repo.save(&operation).map_err(|_|PrepareError::PersistenceFailed)?;return Ok(operation)}let device=JsonDeviceRepository::new(dir).load_all().into_iter().find(|d|d.id==operation.device_id).ok_or(PrepareError::DeviceTargetUnavailable)?;let unit=operation.transient_unit_id.as_deref().filter(|v|ManagedWorkloadOperation::is_valid_transient_unit_id(v)).ok_or(PrepareError::Internal)?;let command=fixed_detached_status_command(unit).ok_or(PrepareError::Internal)?;let result=match executor.execute_bounded(&target(&device),&command,TIMEOUT,LIMITS){Ok(value)=>value,Err(_)=>return Ok(operation)};let mut initiated=false;let mut failed=false;match classify_systemd_show(&result.stdout){Some(DetachedUnitState::Running)=>{operation.state=ManagedWorkloadOperationState::Deploying;operation.dispatch_state=ManagedWorkloadDispatchState::Accepted;operation.failure=None;initiated=true;}Some(DetachedUnitState::Success)=>{operation.state=ManagedWorkloadOperationState::AwaitingVerification;operation.dispatch_state=ManagedWorkloadDispatchState::Accepted;operation.failure=None;}Some(DetachedUnitState::Failed)=>{operation.state=ManagedWorkloadOperationState::DeploymentFailed;operation.failure=Some(ManagedWorkloadFailure::DeploymentFailed);operation.completed_at=Some(Utc::now().to_rfc3339());failed=true;}Some(DetachedUnitState::Missing)=>{operation.state=ManagedWorkloadOperationState::DispatchUncertain;operation.dispatch_state=ManagedWorkloadDispatchState::Uncertain;operation.failure=Some(ManagedWorkloadFailure::OutcomeUncertain);}None=>return Ok(operation)}repo.save(&operation).map_err(|_|PrepareError::PersistenceFailed)?;let activity=JsonActivityRepository::new(dir);if initiated{emit_workload_activity(&repo,&activity,&mut operation,true)}if failed{emit_workload_activity(&repo,&activity,&mut operation,false)}Ok(operation)}
fn fixed_verify_command(action_id:&str,target:&TargetRevision)->Option<String>{trust_probe_command(action_id).ok().map(|_|format!("'{ACTION_ROOT}/{action_id}' verify {}",target.as_str()))}
fn persist_verification_failure(repo:&JsonManagedWorkloadOperationRepository,operation:&mut ManagedWorkloadOperation)->Result<(),VerificationError>{operation.state=ManagedWorkloadOperationState::VerificationFailed;operation.failure=Some(ManagedWorkloadFailure::VerificationFailed);operation.completed_at=Some(Utc::now().to_rfc3339());repo.save(operation).map_err(|_|VerificationError::PersistenceFailed)}
pub(crate) fn verify_deployed_revision_with(dir:&std::path::Path,persisted:&ManagedWorkloadOperation,executor:&dyn RemoteExecutor)->Result<ManagedWorkloadOperation,VerificationError>{if persisted.state!=ManagedWorkloadOperationState::AwaitingVerification{return Err(VerificationError::InvalidLifecycle)}let repo=JsonManagedWorkloadOperationRepository::new(dir);if repo.get(&persisted.device_id,&persisted.workload_id).as_ref()!=Some(persisted){return Err(VerificationError::PersistenceFailed)}let mut operation=persisted.clone();let outcome=(||->Result<(),VerificationError>{let workload=JsonManagedWorkloadRepository::new(dir).load().workloads.into_iter().find(|w|w.id==operation.workload_id).ok_or(VerificationError::WorkloadUnavailable)?;if !workload.enabled||workload.device_id!=operation.device_id||workload.action_id!=operation.action_id||workload.config_revision!=operation.config_revision{return Err(VerificationError::WorkloadUnavailable)}let device=JsonDeviceRepository::new(dir).load_all().into_iter().find(|d|d.id==operation.device_id).ok_or(VerificationError::DeviceTargetUnavailable)?;validate_ssh_username(&device.ssh_username).map_err(|_|VerificationError::DeviceTargetUnavailable)?;let trusted=executor.execute_bounded(&target(&device),&trust_probe_command(&operation.action_id).map_err(|_|VerificationError::TrustFailed)?,TIMEOUT,LIMITS).map_err(|e|verification_ssh_error(&e))?;let action=parse_trust_probe(&operation.action_id,&trusted.stdout).map_err(|_|VerificationError::TrustFailed)?;if action.sha256!=operation.trusted_action_digest{return Err(VerificationError::TrustFailed)}let expected=TargetRevision::parse(&operation.target_revision).map_err(|_|VerificationError::Internal)?;let command=fixed_verify_command(&operation.action_id,&expected).ok_or(VerificationError::Internal)?;let reply=executor.execute_bounded(&target(&device),&command,TIMEOUT,LIMITS).map_err(|e|verification_ssh_error(&e))?;if reply.timed_out{return Err(VerificationError::TimedOut)}if reply.exit_code!=Some(0){return Err(VerificationError::TransportFailed)}let deployed=parse_verify(&reply.stdout).map_err(verification_protocol_error)?;if deployed!=expected{return Err(VerificationError::DeployedRevisionMismatch)}Ok(())})();match outcome{Ok(())=>{operation.state=ManagedWorkloadOperationState::RevisionVerified;operation.failure=None;repo.save(&operation).map_err(|_|VerificationError::PersistenceFailed)?;Ok(operation)}Err(error)=>{persist_verification_failure(&repo,&mut operation)?;Err(error)}}}
pub fn prepare_with(dir:&std::path::Path,workload_id:&str,executor:&dyn RemoteExecutor,coordinator:&DeviceMaintenanceCoordinator)->Result<PreparedWorkload,PrepareError>{let workloads=JsonManagedWorkloadRepository::new(dir).load();let w=workloads.workloads.into_iter().find(|w|w.id==workload_id).ok_or(PrepareError::WorkloadNotFound)?;if !w.enabled{return Err(PrepareError::WorkloadDisabled)}let device=JsonDeviceRepository::new(dir).load_all().into_iter().find(|d|d.id==w.device_id).ok_or(PrepareError::DeviceTargetUnavailable)?;let _claim=coordinator.try_claim(&w.device_id,MaintenanceOperationKind::WorkloadDeploy).ok_or(PrepareError::MaintenanceConflict)?;let evidence=prepare_evidence(&w,&device,executor)?;let now=Utc::now().to_rfc3339();let op=ManagedWorkloadOperation{schema_version:1,id:uuid::Uuid::new_v4().to_string(),device_id:w.device_id,workload_id:w.id,action_id:w.action_id,config_revision:w.config_revision,trusted_action_digest:evidence.action_digest,target_revision:evidence.target_revision.as_str().into(),deployment_fingerprint:evidence.fingerprint,transient_unit_id:None,dispatch_state:ManagedWorkloadDispatchState::NotAttempted,state:ManagedWorkloadOperationState::Prepared,created_at:now.clone(),prepared_at:Some(now),started_at:None,observation_deadline:None,completed_at:None,failure:None,initiated_activity_emitted:false,failure_activity_emitted:false};JsonManagedWorkloadOperationRepository::new(dir).save(&op).map_err(|_|PrepareError::PersistenceFailed)?;Ok(PreparedWorkload{operation:op,change_count:evidence.change_count})}
#[cfg(test)] mod tests { use super::*; use crate::{domain::{device::{Device,DeviceType},managed_workload::{ManagedWorkload,ManagedWorkloadFile}},infrastructure::{managed_workload_trust::ActionTrustError,ssh::{RemoteExecutionResult,SshError}},storage::{device_repository::DeviceRepository,managed_workload_repository::ManagedWorkloadRepository,managed_workload_operation_repository::JsonManagedWorkloadOperationRepository}}; use std::{collections::VecDeque,sync::Mutex}; struct Script{replies:Mutex<VecDeque<RemoteExecutionResult>>,seen:Mutex<Vec<(String,String,u16,String)>>} impl RemoteExecutor for Script{fn execute(&self,t:&SshTarget,c:&str,_:Duration)->Result<RemoteExecutionResult,SshError>{self.seen.lock().unwrap().push((c.into(),t.host.clone(),t.port,t.username.clone()));Ok(self.replies.lock().unwrap().pop_front().unwrap())}} fn ok(s:String)->RemoteExecutionResult{RemoteExecutionResult{exit_code:Some(0),stdout:s,stderr:"raw-secret".into(),duration_ms:1,timed_out:false}} #[test] fn prepare_error_helpers_map_failures_deterministically(){assert_eq!(ssh_error(&SshError::RemoteCommandTimeout),PrepareError::TimedOut);assert_eq!(ssh_error(&SshError::OutputLimitExceeded),PrepareError::OutputLimitExceeded);assert_eq!(ssh_error(&SshError::RemoteCommandError{exit_code:Some(23),stderr:"FAKE_STDERR".into()}),PrepareError::TransportFailed);assert_eq!(trust_error(&ActionTrustError::ActionUnavailable),PrepareError::ActionUnavailable);assert_eq!(trust_error(&ActionTrustError::TrustFailure),PrepareError::ActionTrustFailed);assert_eq!(protocol_error(PrepareContractError::Malformed),PrepareError::PrepareProtocolInvalid);assert_eq!(protocol_error(PrepareContractError::UnsupportedVersion),PrepareError::PrepareProtocolUnsupported);assert_eq!(protocol_error(PrepareContractError::InvalidTarget),PrepareError::TargetRevisionInvalid);} #[test] fn prepare_error_display_excludes_untrusted_details(){let injected=["/fake/path", "fake command --secret", "FAKE_STDOUT", "FAKE_STDERR", "FAKE_ENV=present", "FAKE_SECRET_VALUE"];for error in [PrepareError::ActionTrustFailed,PrepareError::ActionUnavailable,PrepareError::TransportFailed,PrepareError::TimedOut,PrepareError::OutputLimitExceeded,PrepareError::PrepareProtocolInvalid,PrepareError::PrepareProtocolUnsupported,PrepareError::TargetRevisionInvalid]{let display=error.to_string();for value in injected{assert!(!display.contains(value),"{error:?} exposed {value}");}}} #[test] fn fixed_prepare_persists_and_releases_claim(){let d=tempfile::tempdir().unwrap();let device=Device{id:"pi5".into(),name:"p".into(),host:"host.example".into(),ssh_port:2222,ssh_username:"deploy".into(),description:None,device_type:DeviceType::RaspberryPi,monitoring_enabled:true,refresh_interval_seconds:None,notify_on_device_offline:true,notify_on_container_failure:true,notify_on_container_unhealthy:true,services:vec![],created_at:"x".into(),updated_at:"x".into()};JsonDeviceRepository::new(d.path()).save_all(&[device]).unwrap();let w=ManagedWorkload{id:"finance".into(),device_id:"pi5".into(),name:"Finance".into(),action_id:"personal-finance".into(),compose_project:Some("finance".into()),required_compose_services:vec!["app".into()],required_service_health_ids:vec![],enabled:true,config_revision:1};JsonManagedWorkloadRepository::new(d.path()).save(&ManagedWorkloadFile{schema_version:1,workloads:vec![w]}).unwrap();let e=Script{replies:Mutex::new(VecDeque::from(vec![ok(format!("PIHUB_M17_TRUST=trusted\nPIHUB_M17_ACTION_DIGEST={}\n","a".repeat(64))),ok(format!(r#"{{"protocolVersion":1,"status":"ready","currentRevision":"{}","targetRevision":"{}","changeCount":2}}"#,"b".repeat(40),"c".repeat(40)))])),seen:Mutex::new(vec![])};let c=DeviceMaintenanceCoordinator::new();let r=prepare_with(d.path(),"finance",&e,&c).unwrap();assert_eq!(r.operation.target_revision,"c".repeat(40));assert_eq!(r.operation.trusted_action_digest,"a".repeat(64));let seen=e.seen.lock().unwrap();assert_eq!(seen.len(),2);assert_eq!(seen[0].1,"host.example");assert_eq!(seen[0].2,2222);assert_eq!(seen[0].3,"deploy");assert!(seen[1].0.ends_with("personal-finance' prepare"));assert!(!seen.iter().any(|x|x.0.contains("apply")||x.0.contains("systemd-run")));drop(seen);assert_eq!(JsonManagedWorkloadOperationRepository::new(d.path()).get("pi5","finance"),Some(r.operation));assert!(c.try_claim("pi5",MaintenanceOperationKind::WorkloadDeploy).is_some());}}
